#nullable enable
using System.Collections.Generic;
using System.Linq;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp.Syntax;

namespace AlephMapper.Helpers;

internal static class RoslynCompatibility
{
    public static void AddEmbeddedAttributeDefinition(IncrementalGeneratorPostInitializationContext context)
    {
#if ALEPHMAPPER_ROSLYN5
        context.AddEmbeddedAttributeDefinition();
#else
        context.AddSource("Microsoft.CodeAnalysis.EmbeddedAttribute.g.cs", """
            // <auto-generated/>
            namespace Microsoft.CodeAnalysis
            {
                [global::System.Runtime.CompilerServices.CompilerGenerated]
                [Embedded]
                [global::System.AttributeUsage(global::System.AttributeTargets.All, AllowMultiple = false, Inherited = false)]
                internal sealed class EmbeddedAttribute : global::System.Attribute { }
            }
            """);
#endif
    }

    public static bool IsExtensionType(INamedTypeSymbol? type)
    {
#if ALEPHMAPPER_ROSLYN5
        return type?.IsExtension == true;
#else
        return false;
#endif
    }

    public static IParameterSymbol? GetExtensionReceiver(INamedTypeSymbol type)
    {
#if ALEPHMAPPER_ROSLYN5
        return type.ExtensionParameter;
#else
        return null;
#endif
    }

    public static bool IsExtensionMember(SyntaxNode node)
    {
#if ALEPHMAPPER_ROSLYN5
        return node.Parent is ExtensionBlockDeclarationSyntax;
#else
        return false;
#endif
    }

    public static IEnumerable<MemberDeclarationSyntax> GetExtensionMembers(ClassDeclarationSyntax declaration)
    {
#if ALEPHMAPPER_ROSLYN5
        return declaration.Members.OfType<ExtensionBlockDeclarationSyntax>().SelectMany(block => block.Members);
#else
        return Enumerable.Empty<MemberDeclarationSyntax>();
#endif
    }
}
